(()=>{const c=document.querySelector("#journal-list"),a=document.querySelector("#journal-status");if(!c)return;async function C(){try{const n=await fetch("/api/journal",{credentials:"same-origin",headers:{Accept:"application/json"}}),o=await n.json();if(n.status===401){a.textContent="Sign in with Google to open your private journal.";return}if(!n.ok)throw new Error(o.error||"Could not load your journal.");c.replaceChildren(),a.textContent=o.analyses.length?`${o.analyses.length} saved analysis${o.analyses.length===1?"":"es"}.`:"No saved analyses yet. After you review a report, choose \u201CSave to my journal\u201D to add it here.",o.analyses.forEach(e=>{const r=document.createElement("article");r.className="journal-card panel";const u=document.createElement("h2");u.textContent=e.instrument||"Chart analysis";const d=document.createElement("p");d.className="journal-date",d.textContent=new Date(e.created_at).toLocaleString();const s=document.createElement("img");s.src=`/api/journal/${encodeURIComponent(e.id)}/chart`,s.alt=`Saved chart for ${e.instrument||"analysis"}`,s.loading="lazy";const m=document.createElement("details"),p=document.createElement("summary");p.textContent=`${e.result?.signal||"Analysis"} report \xB7 ${e.timeframe||"Timeframe not recorded"}`;const i=document.createElement("div");i.className="journal-report prose";const y=document.createElement("p");y.textContent=e.result?.analysis||"No detailed analysis was saved.";const h=document.createElement("p");h.textContent=e.result?.rationale?`Rationale: ${e.result.rationale}`:"",i.append(y,h),m.append(p,i);const t=document.createElement("button");t.type="button",t.className="button danger",t.textContent="Delete saved analysis",t.addEventListener("click",async()=>{if(window.confirm("Delete this saved chart and its analysis report?")){t.disabled=!0;try{const l=await fetch(`/api/journal/${encodeURIComponent(e.id)}`,{method:"DELETE",credentials:"same-origin",headers:{Accept:"application/json"}}),E=await l.json();if(!l.ok)throw new Error(E.error||"Could not delete the saved analysis.");r.remove(),a.textContent="Saved analysis deleted."}catch(l){t.disabled=!1,a.textContent=l.message}}}),r.append(u,d,s,m,t),c.append(r)})}catch(n){a.textContent=n.message}}C()})();
